src='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each 8-connected non-background component carries its marker color.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            colors = set()
            while q:
                y, x = q.pop()
                cells.append((y, x))
                if grid[y][x] not in (0, 1):
                    colors.add(grid[y][x])
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            q.append((ny, nx))
            if colors:
                components.append((set(cells), colors))

    # Color the strict interior of every maximal solid rectangle in a marked component.
    for cells, colors in components:
        color = min(colors)
        for top in range(h):
            for bottom in range(top + 2, h):
                for left in range(w):
                    for right in range(left + 2, w):
                        rect = [(y, x) for y in range(top, bottom + 1) for x in range(left, right + 1)]
                        if not all((y, x) in cells for y, x in rect):
                            continue
                        # A rectangle is maximal when it cannot be extended on any side.
                        if top > 0 and all((top - 1, x) in cells for x in range(left, right + 1)):
                            continue
                        if bottom + 1 < h and all((bottom + 1, x) in cells for x in range(left, right + 1)):
                            continue
                        if left > 0 and all((y, left - 1) in cells for y in range(top, bottom + 1)):
                            continue
                        if right + 1 < w and all((y, right + 1) in cells for y in range(top, bottom + 1)):
                            continue
                        for y in range(top + 1, bottom):
                            for x in range(left + 1, right):
                                if grid[y][x] == 1 or grid[y][x] in colors:
                                    out[y][x] = color
    return out
'''
